import bcrypt from "bcryptjs";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
  // Absent for users who only ever signed in via an OAuth provider (e.g. Google).
  passwordHash?: string;
};

const users: User[] = [
  { id: "1", email: "ada@example.com", name: "Ada", createdAt: "2026-01-04" },
  { id: "2", email: "grace@example.com", name: "Grace", createdAt: "2026-02-11" },
];

let nextId = users.length + 1;

export async function listUsers(): Promise<User[]> {
  return users;
}

export async function getUser(id: string): Promise<User | undefined> {
  return users.find((u) => u.id === id);
}

export async function getUserByEmail(email: string): Promise<User | undefined> {
  const normalized = email.trim().toLowerCase();
  return users.find((u) => u.email.toLowerCase() === normalized);
}

// Session handling lives in src/auth.ts; this just resolves the id the
// session points at against the in-memory store.
export async function getCurrentUser(id: string): Promise<User | undefined> {
  return getUser(id);
}

export async function createUserWithPassword(
  email: string,
  name: string,
  password: string
): Promise<User> {
  const normalized = email.trim().toLowerCase();
  if (await getUserByEmail(normalized)) {
    throw new Error("A user with this email already exists.");
  }
  const passwordHash = await bcrypt.hash(password, 10);
  const user: User = {
    id: String(nextId++),
    email: normalized,
    name,
    createdAt: new Date().toISOString().slice(0, 10),
    passwordHash,
  };
  users.push(user);
  return user;
}

// Used by the Google sign-in callback: find-or-create by email, no password set.
export async function findOrCreateOAuthUser(email: string, name: string): Promise<User> {
  const existing = await getUserByEmail(email);
  if (existing) return existing;
  const user: User = {
    id: String(nextId++),
    email: email.trim().toLowerCase(),
    name,
    createdAt: new Date().toISOString().slice(0, 10),
  };
  users.push(user);
  return user;
}

export async function verifyPassword(user: User, password: string): Promise<boolean> {
  if (!user.passwordHash) return false;
  return bcrypt.compare(password, user.passwordHash);
}

