"use client";

import Link from "next/link";
import { useActionState } from "react";
import { signUpAction, type SignUpState } from "./actions";

const initialState: SignUpState = {};

export default function SignUpPage() {
  const [state, formAction, pending] = useActionState(signUpAction, initialState);

  return (
    <main className="mx-auto flex max-w-sm flex-1 flex-col justify-center p-8">
      <h1 className="text-2xl font-semibold">Create an account</h1>

      <form action={formAction} className="mt-6 flex flex-col gap-3">
        <input
          name="name"
          type="text"
          placeholder="Name"
          required
          className="rounded border px-3 py-2 text-sm"
        />
        <input
          name="email"
          type="email"
          placeholder="Email"
          required
          className="rounded border px-3 py-2 text-sm"
        />
        <input
          name="password"
          type="password"
          placeholder="Password (min 8 characters)"
          minLength={8}
          required
          className="rounded border px-3 py-2 text-sm"
        />
        {state.error && <p className="text-sm text-red-600">{state.error}</p>}
        <button
          type="submit"
          disabled={pending}
          className="rounded bg-foreground px-3 py-2 text-sm font-medium text-background disabled:opacity-60"
        >
          {pending ? "Creating account…" : "Sign up"}
        </button>
      </form>

      <div className="mt-4 text-center text-xs uppercase tracking-wide opacity-50">or</div>

      <form
        action={async () => {
          "use server";
          const { signIn } = await import("@/auth");
          await signIn("google", { redirectTo: "/dashboard" });
        }}
        className="mt-4"
      >
        <button
          type="submit"
          className="w-full rounded border px-3 py-2 text-sm font-medium"
        >
          Continue with Google
        </button>
      </form>

      <p className="mt-6 text-sm opacity-70">
        Already have an account?{" "}
        <Link href="/sign-in" className="font-medium underline">
          Sign in
        </Link>
      </p>
    </main>
  );
}

